function result=runV4BDiagnosticFrames()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();p=v4DefaultBParameters();schedule=v4ContinuousPassSchedule(c);state=struct('time',schedule.passStartTimeSec,'phase',0,'cross',struct());rows=cell(sum(schedule.metricEligible),12);out=0;
for frameIndex=1:schedule.frameCount
    ledger=v4RandomLedger(c,'validation',2,1,frameIndex);frame=v4GenerateContinuousFrame(c,state.time,-21,ledger,state.phase,'AWGN');state.time=frame.nextFrameStartTimeSec;state.phase=frame.nextFrameStartPhaseRad;if ~schedule.metricEligible(frameIndex),state.cross=struct();continue,end
    bootstrap=v4CommonBootstrap(frame.observation.rxPhysical(1:8,:),c,SearchStepBins=p.searchStepBins);measurement=schedule.frameStartTimeSec(frameIndex)+4*c.symbolDurationSec;[rate,state.cross]=v4CrossFrameRateUpdate(state.cross,measurement,mean(bootstrap.cfoBins),bootstrap.rateBinsPerSec,c,p);rx=v4Stage55Decode(frame.observation,bootstrap,c,p,CrossFrameRateBinsPerSec=rate,CrossFrameHistoryCount=state.cross.historyCount);m=v4EvaluateFrame(rx,frame.truth,c);accepted=rx.virtualPilotAccepted;out=out+1;rows(out,:)={frameIndex,schedule.frameCenterTimeSec(frameIndex),state.cross.historyCount,bootstrap.rateBinsPerSec,rate,m.ser,m.hardBer,m.softBer,m.cfoRmseBins,sum(accepted),sum(accepted&rx.detectedPhysicalBins~=frame.truth.payloadPhysicalBins),sum(rx.phasePairUsed)};
end
records=cell2table(rows,'VariableNames',{'frameIndex','centerTimeSec','historyCount','bootstrapRate','crossRate','ser','hardBer','mlBer','cfoRmseBins','vpAccepted','vpFalseAccepted','phasePairs'});result=struct('status','PASS','records',records,'meanSer',mean(records.ser),'meanMlBer',mean(records.mlBer),'totalVpAccepted',sum(records.vpAccepted),'totalVpFalse',sum(records.vpFalseAccepted));folder=fullfile(root,'results','b_mechanism');save(fullfile(folder,'stage55_diagnostic_allframes.mat'),'result','-v7.3');writetable(records,fullfile(folder,'stage55_diagnostic_allframes.csv'));
end
